r(coalesce(b.shippingpackagestatus,b.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(b.shippingpackagestatus,b.shipping_status)) FINAL_SHIPPING_STATUS ,saleOrderItemCode as SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID as SALES_ORDER_ITEM_ID ,AWB ,null as payment_gateway ,upper(payment_mode) payment_mode ,upper(coalesce(COURIER, courier_aggregator)) COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date as delivered_date ,case when upper(FINAL_SHIPPING_STATUS) in (\'DELIVERED\') then 1 end AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,case when return_flag = 1 then suborder_quantity::int end returned_quantity ,case when return_flag = 1 then selling_price::float end returned_sales ,case when return_flag = 0 and lower(order_status) in (\'cancelled\') then suborder_quantity::int end cancelled_quantity ,new_customer_flag::varchar as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,case when order_status=\'COMPLETE\' then delivered_date::date-order_date::date else current_date - order_date::Date end as days_in_shipment ,NULL AS ACQUSITION_DATE ,b.commonsku sku_code ,upper(b.product_name_final) PRODUCT_NAME_FINAL ,upper(b.Product_Category) PRODUCT_CATEGORY ,upper(b.product_sub_category) PRODUCT_SUB_CATEGORY ,null as brand ,upper(warehouse_name) warehouse ,pincode ,courierstatus ,selling_price line_item_sales ,null refund_amount_without_lineitem ,null as discount_code ,null as Cogs from datalake_db.kaya.dwh_unicommerce_fact_items b where not(lower(b.marketplace) like any (\'%shopify%\',\'custom\')) ; create or replace table datalake_db.kaya.dwh_Final_customerID as with new_phone_numbers as ( select phone, contact_num, 19700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) as contact_num, phone from datalake_db.kaya.dwh_sales_consolidated_intermediate ) a ), int as ( select contact_num, email, coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email, maple_monk_id, 19800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10)) as contact_num, e.email, maple_monk_id from ( select phone as contact_num, email from datalake_db.kaya.dwh_sales_consolidated_intermediate ) e left join new_phone_numbers p on p.contact_num = right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10) ) a ) b ) select contact_num, email, maple_monk_id from int where coalesce(contact_num,email) is not NULL ; create or replace table datalake_db.kaya.dwh_sales_consolidated as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(order_date) over(partition by customer_id_final) as acquisition_date, min(case when lower(m.order_status) not in (\'cancelled\') then order_date end) over(partition by customer_id_final) as first_complete_order_date, m.*, coalesce(m.order_status, m.shipping_status) as final_status from ( select c.maple_monk_id as maple_monk_id_phone, o.* from datalake_db.kaya.dwh_sales_consolidated_intermediate o left join ( select * from ( select contact_num phone, maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) magic from datalake_db.kaya.dwh_Final_customerID ) where magic =1 )c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10) )m left join ( select distinct maple_monk_id, email from datalake_db.kaya.dwh_Final_customerID where contact_num is null )d on d.email = m.email ; ALTER TABLE datalake_db.kaya.dwh_sales_consolidated drop COLUMN new_customer_flag ; ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN new_customer_flag varchar(50); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE datalake_db.kaya.dwh_sales_consolidated drop COLUMN acquisition_product ; ALTER TABLE datalake_db.kaya.dwh_sales_consolidated ADD COLUMN acquisition_product varchar(1677721