lete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM datalake_db.kaya.dwh_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' ELSE new_customer_flag_month END; create or replace temporary table datalake_db.kaya.dwh_temp_source_1 AS SELECT DISTINCT customer_id_final, channel, marketplace FROM ( SELECT DISTINCT customer_id_final, order_date, channel as channel, shop_name as marketplace, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER ( partition BY customer_id_final) firstOrderdate FROM datalake_db.kaya.dwh_sales_consolidated ) res WHERE order_date=firstorderdate; UPDATE datalake_db.kaya.dwh_sales_consolidated AS a SET a.acquisition_channel=b.channel FROM datalake_db.kaya.dwh_temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated AS a SET a.acquisition_marketplace=b.marketplace FROM datalake_db.kaya.dwh_temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE datalake_db.kaya.dwh_temp_product_1 AS SELECT DISTINCT customer_id_final, product_name, product_name_final, product_category, product_sub_category, sku, Row_number() OVER (partition BY customer_id_final ORDER BY SELLING_PRICE DESC) rowid FROM ( SELECT DISTINCT customer_id_final, order_date, product_name, product_name_final, product_category, product_sub_category, sku, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM datalake_db.kaya.dwh_sales_consolidated )res WHERE order_date=firstorderdate; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.acquisition_product=B.product_name FROM ( SELECT * FROM datalake_db.kaya.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.acquisition_product_category=B.product_category FROM ( SELECT * FROM datalake_db.kaya.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.acquisition_product_sub_category=B.product_sub_category FROM ( SELECT * FROM datalake_db.kaya.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE datalake_db.kaya.dwh_sales_consolidated AS A SET A.acquisition_SKUCODE=B.SKU FROM ( SELECT * FROM datalake_db.kaya.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; Create or Replace table datalake_db.kaya.dwh_sales_consolidated as select CUSTOMER_ID_FINAL ,ACQUISITION_DATE ,FIRST_COMPLETE_ORDER_DATE ,MAPLE_MONK_ID_PHONE ,CUSTOMER_ID ,SHOP_NAME ,MARKETPLACE ,CHANNEL ,SOURCE ,PLATFORM_TRAFFIC ,Branding ,ORDER_ID ,REFERENCE_CODE ,PHONE ,NAME ,EMAIL ,SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,PRODUCT_NAME ,CURRENCY ,CITY ,STATE ,ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,QUANTITY ,GROSS_SALES_BEFORE_TAX ,DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE ,MRP_SALES ,OMS_ORDER_STATUS ,SHIPPING_STATUS ,FINAL_SHIPPING_STATUS ,SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID ,AWB ,PAYMENT_GATEWAY ,PAYMENT_MODE ,COURIER ,DISPATCH_DATE ,DELIVERED_DATE ,DELIVERED_STATUS ,RETURN_FLAG ,RETURNED_QUANTITY ,RETURNED_SALES ,CANCELLED_QUANTITY ,DAYS_IN_SHIPMENT ,ACQUSITION_DATE ,SKU_CODE ,PRODUCT_NAME_FINAL ,PRODUCT_CATEGORY ,PRODUCT_SUB_CATEGORY ,BRAND ,WAREHOUSE ,PINCODE ,EASYECOM_STATUS ,LINE_ITEM_SALES ,REFUND_AMOUNT_WITHOUT_LINEITEM ,DISCOUNT_CODE ,FINAL_STATUS ,NEW_CUSTOMER_FLAG ,NEW_CUSTOMER_FLAG_MONTH ,ACQUISITION_PRODUCT ,ACQUISITION_SKUCODE ,ACQUISITION_PRODUCT_SUB_CATEGORY ,ACQUISITION_PRODUCT_CATEGORY ,ACQUISITION_CHANNEL ,ACQUISITION_MARKETPLACE ,null as Return_Sales ,null as REFUND_QU